descriptor.templateCss:
.pcs-card-container.thermal {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 10px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #f97316;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
  transition: border-top-color 0.3s ease;
}
.pcs-card-container.thermal.warning { border-top-color: #f59e0b; }
.pcs-card-container.thermal.danger { border-top-color: #ef4444; }
.pcs-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.pcs-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #94a3b8;
}
.pcs-icon { font-size: 16px; }
.pcs-badge.thermal {
  font-size: 11px;
  font-weight: 700;
  padding: 2px 10px;
  border-radius: 20px;
}
.pcs-badge.thermal.safe { color: #64B856; border: 1.5px solid #64B856; background: rgba(100, 184, 86, 0.12); }
.pcs-badge.thermal.warning { color: #f59e0b; border: 1.5px solid #f59e0b; background: rgba(245, 158, 11, 0.1); }
.pcs-badge.thermal.danger { color: #ef4444; border: 1.5px solid #ef4444; background: rgba(239, 68, 68, 0.15); }
.pcs-main-metric {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 4px 0;
}
.main-num.thermal {
  font-size: 34px;
  font-weight: 800;
  line-height: 1;
}
.main-num.thermal.safe { color: #f97316; }
.main-num.thermal.warning { color: #f59e0b; }
.main-num.thermal.danger { color: #ef4444; }
.main-unit { font-size: 16px; font-weight: 600; color: #94a3b8; }
.thermal-matrix {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin: 6px 0;
}
.thermal-col {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(100, 184, 86, 0.15);
  border-radius: 10px;
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.col-header {
  font-size: 11px;
  font-weight: 700;
  color: #94a3b8;
  border-bottom: 1px solid rgba(100, 184, 86, 0.15);
  padding-bottom: 3px;
}
.temp-row {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
}
.t-label { color: #64748b; }
.t-value.safe { color: #64B856; font-weight: 700; }
.t-value.warning { color: #f59e0b; font-weight: 700; }
.t-value.danger { color: #ef4444; font-weight: 700; }
.t-value-amb { color: #94a3b8; font-weight: 600; }
.pcs-footer {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #64748b;
  border-top: 1px solid rgba(148, 163, 184, 0.12);
  padding-top: 8px;
  margin-top: 4px;
}

descriptor.controllerScript:
self.onInit = function() { self.onDataUpdated(); };
self.onDataUpdated = function() {
  var data = self.ctx.data;
  var igbt = [48.5, 47.8, 49.1];
  var amb = [29.2, 28.9, 29.5];

  if (data && data.length > 0) {
    for (var i = 0; i < data.length; i++) {
      var item = data[i];
      if (item.data && item.data.length > 0) {
        var v = parseFloat(item.data[item.data.length - 1][1]);
        var k = (item.dataKey.label || item.dataKey.name || "").toLowerCase();
        if (!isNaN(v)) {
          if (k.indexOf('igbt_pcs1') !== -1) igbt[0] = v;
          else if (k.indexOf('igbt_pcs2') !== -1) igbt[1] = v;
          else if (k.indexOf('igbt_pcs3') !== -1) igbt[2] = v;
          else if (k.indexOf('amb_pcs1') !== -1) amb[0] = v;
          else if (k.indexOf('amb_pcs2') !== -1) amb[1] = v;
          else if (k.indexOf('amb_pcs3') !== -1) amb[2] = v;
        }
      }
    }
  }

  var maxTemp = Math.max.apply(null, igbt);
  var status = 'safe';
  var badgeText = 'ÓPTIMO (<65°C)';
  if (maxTemp >= 80) {
    status = 'danger';
    badgeText = 'CRÍTICO (>80°C)';
  } else if (maxTemp >= 65) {
    status = 'warning';
    badgeText = 'ELEVADO (>65°C)';
  }

  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (container) {
    var card = container.querySelector('#thermal-card');
    if (card) card.className = 'pcs-card-container thermal ' + status;

    var elMax = container.querySelector('#max-temp-val');
    if (elMax) {
      elMax.textContent = maxTemp.toFixed(1);
      elMax.className = 'main-num thermal ' + status;
    }

    var elBadge = container.querySelector('#thermal-badge');
    if (elBadge) {
      elBadge.textContent = badgeText;
      elBadge.className = 'pcs-badge thermal ' + status;
    }

    for (var idx = 0; idx < 3; idx++) {
      var elI = container.querySelector('#t-igbt' + (idx + 1));
      var elA = container.querySelector('#t-amb' + (idx + 1));
      if (elI) {
        elI.textContent = igbt[idx].toFixed(1) + ' °C';
        elI.className = 't-value ' + (igbt[idx] >= 80 ? 'danger' : (igbt[idx] >= 65 ? 'warning' : 'safe'));
      }
      if (elA) elA.textContent = amb[idx].toFixed(1) + ' °C';
    }
  }
};
self.onDestroy = function() {};
